// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 v1, uint256 v2) public {
        vm.assume(v1 != v2);
        bool ok1;
        try c.SetMinSum(v1) { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);

        bool ok2;
        try c.SetMinSum(v2) { ok2 = true; } catch { ok2 = false; }

        // General rule: while not Initialized, SetMinSum always succeeds and
        // MinSum equals the most recent value passed to it.
        assertTrue(ok2 && c.MinSum() == v2);
    }
}
